with cleaned as (select *, hour(paid_at) as paid_at_hour, coalesce(method, 'N/A') as method_clean from payments where paid_at > date '2023-09-02' and order_id is not null) select id, order_id, method, paid_at, status, paid_at_hour, sum(paid_at_hour) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as cumulative_paid_at_hour, avg(amount) over (partition by order_id order by cast(paid_at as bigint) range between 7776000 preceding and current row) as amount_avg_90d, max(paid_at_hour) over (partition by order_id order by cast(paid_at as bigint) range between 7776000 preceding and current row) as paid_at_hour_max_90d from cleaned where paid_at < '2023-11-21'
